+export function reply_continents_shown() {
+  "The continents, written the way a reply says them back.";
+  "These are kept apart from the country lists on purpose. Those lists also decide who is answered as being from somewhere, and I am from Africa has not been asked about, so joining them here would change that answer without anybody deciding it.";
+  "Australia is not here because it is already a country a reply may name.";
+  let continents = [
+    "Africa",
+    "Antarctica",
+    "Asia",
+    "Europe",
+    "North America",
+    "Oceania",
+    "South America",
+  ];
+  return continents;
+}
